package io.quarkiverse.nativematrix.deployment.orchestrator;

import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Set;
import java.util.function.Consumer;
import java.util.stream.Collectors;

import io.quarkiverse.nativematrix.spi.Platform;

/**
 * Adapts the {@code native-image} arguments generated by Quarkus to the target platform.
 * <p>
 * Quarkus computes the arguments for the machine running the build. A few of them depend on that machine and must be
 * fixed when the executable is built elsewhere.
 */
public final class ArgsAdjuster {

    private static final Set<String> LINUX_ONLY = Set.of("--static", "--static-nolibc", "--libc=musl",
            "-H:+StaticExecutableWithDynamicLibC");

    private ArgsAdjuster() {
    }

    public static List<String> adjust(List<String> args, Platform target, Path nativeSourcesDirectory,
            Consumer<String> warnings) {
        List<String> result = new ArrayList<>(args.size());
        for (String arg : args) {
            if (arg.startsWith("--enable-monitoring=") && target.os() == Platform.Os.WINDOWS) {
                // Quarkus adds heapdump unless the build machine runs Windows; native-image rejects it on Windows
                String options = Arrays.stream(arg.substring("--enable-monitoring=".length()).split(","))
                        .filter(o -> !o.equals("heapdump"))
                        .collect(Collectors.joining(","));
                if (!options.isEmpty()) {
                    result.add("--enable-monitoring=" + options);
                }
                continue;
            }
            if (target.os() != Platform.Os.LINUX && LINUX_ONLY.contains(arg)) {
                warnings.accept("Ignoring " + arg + ": it is only supported on Linux");
                continue;
            }
            // paths of the build machine are made portable by PathRelocator beforehand
            result.add(arg);
        }
        return result;
    }
}
